#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {
TOTAL_STAGES=8
banner "Authenticated production CI setup (operator-driven)"
stage "Stop and review"
cat <<'TEXT'
  This wizard executes no production or GitHub commands. Follow each block manually.
  Deployment is root-equivalent: a stolen key can deploy attacker-controlled code.
  Keep an independent working admin session open throughout; do not replace existing
  authorized_keys or change global SSH settings. Rehearse on a disposable host first.
  Required: completed production cutover, reviewed receiver and compose, amd64 host,
  adequate disk, Docker Compose v2 --wait, Python 3, flock, and a recovery plan.
  Automatic deployment without approval differs from AUTHENTICATED_CI.md. Obtain
  explicit production authorization and understand every successful main push deploys.
TEXT
confirm "Are prerequisites met and automatic deployment authorized?" || exit 1

stage "Verify live host and reviewed revision"
cat <<'TEXT'
  On the server, from a trusted checkout of the exact reviewed revision:
    sha256sum staging_mcp/compose.yaml /etc/di-staging/compose.yaml
    grep '^COMPOSE_SHA =' staging_mcp/receive-production.py
    uname -m; docker compose version; docker compose up --help | grep -- --wait
    sudo test ! -e /etc/di-staging/.env && sudo test ! -L /etc/di-staging/.env
  Both hashes must equal the receiver's COMPOSE_SHA; never overwrite live compose
  to make this pass. Confirm x86_64, container identity/configuration and prerequisites
  against staging_mcp/AUTHENTICATED_CI.md without printing credentials. Coordinate
  users of /run/lock/di-staging-allowlist.lock. Stop on any mismatch.
TEXT
confirm "All checks and review passed?" || exit 1

stage "Install reviewed receiver and command gate"
cat <<'TEXT'
  On the server in the trusted checkout, as an administrator (review before running):
    sudo install -o root -g root -m 0755 staging_mcp/receive-production.py /usr/local/sbin/di-auth-receive
    sudo tee /usr/local/sbin/di-auth-gate >/dev/null <<'GATE'
#!/bin/bash
set -eu
export PATH=/usr/sbin:/usr/bin:/sbin:/bin
cmd=${SSH_ORIGINAL_COMMAND-}
if [[ $cmd =~ ^sudo\ -n\ /usr/local/sbin/di-auth-receive\ ([0-9a-f]{40})$ ]]; then
  exec /usr/bin/sudo -n /usr/local/sbin/di-auth-receive "${BASH_REMATCH[1]}"
fi
printf '%s\n' 'Rejected command' >&2
exit 1
GATE
    sudo chown root:root /usr/local/sbin/di-auth-gate
    sudo chmod 0755 /usr/local/sbin/di-auth-gate
    namei -l /usr/local/sbin/di-auth-gate
    namei -l /usr/local/sbin/di-auth-receive
  Verify each parent and both files are root-owned and not writable by others;
  resolve symlinks and stop if any path component is untrusted. Gate preserves stdin.
TEXT
confirm "Installed and verified?" || exit 1

stage "Dedicated account and sudo policy"
cat <<'TEXT'
  Use a new account named di-auth-deploy, never an existing human account.
  These Linux commands require sudo >= 1.9.10 (sudo -V): regex argument support.
  Stop and obtain a reviewed equivalent if unsupported; do not use a wildcard rule.
    sudo useradd --create-home --shell /bin/bash di-auth-deploy
  Set a random unrecorded password without displaying it:
    sudo sh -ec 'p=$(openssl rand -hex 48); test ${#p} -eq 96; printf "di-auth-deploy:%s\n" "$p" | chpasswd'
  Password login must be disabled for this account via sshd Match User; ensure sshd
  permits public-key login for this non-expired account, and no other keys or auth
  methods. Do not grant Docker group membership or any other sudo privileges.
  Use sudo visudo -f /etc/sudoers.d/di-auth-deploy and add exactly:
    di-auth-deploy ALL=(root) NOPASSWD: /usr/local/sbin/di-auth-receive ^[0-9a-f]{40}$
  Check with sudo visudo -c and sudo -l -U di-auth-deploy; remove conflicting grants.
  Root-owned gate is mandatory: sudo's receiver is privileged, not a sandbox.
TEXT
confirm "Account and sudo policy verified?" || exit 1

stage "Key and SSH restrictions"
cat <<'TEXT'
  On a secure operator workstation, generate a dedicated key in a protected location:
    umask 077; ssh-keygen -t ed25519 -N '' -f "$HOME/.ssh/di-auth-ci"
  Never print, paste into a terminal, commit or share the private key except as the
  GitHub environment secret. On the server install ONLY its public key for the new
  account. Create /etc/ssh/di-auth-keys root:root 0755 and a root:root 0644 file
  /etc/ssh/di-auth-keys/di-auth-deploy containing one line:
    restrict,command="/usr/local/sbin/di-auth-gate" ssh-ed25519 PUBLIC_KEY
  Replace ssh-ed25519 PUBLIC_KEY with the complete generated .pub contents.
  Configure sshd for this account (in a correctly ordered Match User block):
    Match User di-auth-deploy
        AuthorizedKeysFile /etc/ssh/di-auth-keys/%u
        AuthenticationMethods publickey
        PasswordAuthentication no
        KbdInteractiveAuthentication no
        PermitTTY no
        DisableForwarding yes
  Ensure no other authentication source (e.g. AuthorizedKeysCommand, trusted user
  CAs or alternate Match settings) can bypass the gate. Verify sshd -T -C with the
  actual user, source address and host, and sudo sshd -t before reloading sshd.
  Account for sshd Include/Match ordering; do not disrupt other users. Restrict source
  network where practical, noting GitHub-hosted runner IPs change. Keep admin access.
  If the effective configuration cannot ensure key-only forced-command access, STOP.
TEXT
confirm "SSHD configuration checked, reloaded safely and admin access retained?" || exit 1

stage "Pin host key and test gate"
cat <<'TEXT'
  Independently obtain the server host public key fingerprint via a trusted console:
    sudo ssh-keygen -lf /etc/ssh/ssh_host_ed25519_key.pub
  On the workstation scan into a NEW protected file, then compare its fingerprint
  against the console over a separate trusted channel (scan alone is not verification):
    umask 077; ssh-keyscan -t ed25519 YOUR_HOST > "$HOME/.ssh/di-auth-known-hosts"
    ssh-keygen -lf "$HOME/.ssh/di-auth-known-hosts"
  Replace YOUR_HOST with exactly the hostname used by CI. Stop if fingerprints differ.
  Test with ssh -i "$HOME/.ssh/di-auth-ci" -o IdentitiesOnly=yes -o BatchMode=yes
  -o StrictHostKeyChecking=yes -o UserKnownHostsFile="$HOME/.ssh/di-auth-known-hosts"
  di-auth-deploy@YOUR_HOST COMMAND (all on one line). Empty command, id, shell,
  sudo -n /usr/local/sbin/di-auth-receive followed by invalid SHA, extra arguments,
  uppercase SHA, or shell metacharacters must all return nonzero / Rejected command.
  On a disposable equivalent host, test an exact valid command with a real image stream,
  verify stdin reaches receiver and that authorized and unauthorized requests behave
  correctly. Do not send a valid deployment to production merely to test the gate.
TEXT
confirm "Out-of-band host verification and negative/rehearsal tests passed?" || exit 1

stage "GitHub environment and secrets"
cat <<'TEXT'
  In the repository: Settings > Environments > New environment (or select existing)
  > authenticated-production. Restrict deployment branches to main. Do not add
  required reviewers or a wait timer; remove existing ones only with authorization.
  Check repository rules, plan availability, environment protections and organization
  policies actually enforce main-only deployment with no approval. If not, STOP.
  Under Environment secrets (NOT repository secrets), add these four individually:
    AUTH_DEPLOY_SSH_PRIVATE_KEY  complete contents of ~/.ssh/di-auth-ci
    AUTH_DEPLOY_SSH_KNOWN_HOSTS complete verified ~/.ssh/di-auth-known-hosts
    AUTH_DEPLOY_HOST            exact verified hostname (no user or port)
    AUTH_DEPLOY_USER            di-auth-deploy
  Paste privately using GitHub's secret-entry UI; do not echo values or record them.
  Do not put WorkOS credentials or tokens into GitHub. This workflow uses SSH port 22.
  Creating/changing these secrets and protections is a production-impacting action.
TEXT
confirm "Environment protections and four environment secrets configured?" || exit 1

stage "Enable and verify"
cat <<'TEXT'
  Ensure the reviewed workflow is on main and GitHub Actions is enabled only after
  all prior checks: a push to main can immediately deploy without approval. Review
  Actions run and deployed revision after the queue clears; main-tip checking is not
  atomic with pushes or lock delays. Verify health, unauthorized rejection, and
  authorized access separately with a securely handled client (never log tokens).
  On failure consult AUTHENTICATED_CI.md Recovery and coordinate the shared lock.
  Delete the local private key once safely stored in GitHub and no longer needed;
  maintain an out-of-band revocation/rotation plan. This wizard made no changes.
TEXT
pause "Press Enter to finish."
finish
}
run_wizard "$@"; exit
